@Composable
fun SanchesTvApp(
    initialChannelId: String? = null,
    registerKeyHandler: (((KeyEvent) -> Boolean)?) -> Unit
) {
    val context = LocalContext.current
    val controller = remember { ZappController(context) }
    var splash by remember { mutableStateOf(true) }

    DisposableEffect(controller) {
        controller.start()
        registerKeyHandler(controller::handleKey)
        onDispose {
            registerKeyHandler(null)
            controller.close()
        }
    }

    LaunchedEffect(initialChannelId) {
        initialChannelId?.let(controller::openChannelById)
    }

    LaunchedEffect(Unit) {
        delay(650)
        splash = false
    }

    SanchesTheme {
        if (splash) {
            BrandSplash()
        } else if (controller.state.screen == AppScreen.WATCH) {
            WatchScreen(controller)
        } else {
            AppShell(controller)
        }
    }
}

