@Composable
private fun AppShell(controller: ZappController) {
    val state = controller.state

    Row(
        modifier = Modifier
            .fillMaxSize()
            .background(SanchesColors.Background)
    ) {
        NavRail(
            selected = state.screen,
            onNavigate = controller::open
        )

        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
                .background(
                    Brush.verticalGradient(
                        listOf(Color(0xFF0B151D), SanchesColors.Background)
                    )
                )
        ) {
            when (state.screen) {
                AppScreen.HOME -> HomeScreen(state, controller)
                AppScreen.LIVE -> ChannelNavigatorScreen(state, controller)
                AppScreen.MOVIES -> MoviesScreen(controller)
                AppScreen.SERIES -> CuratedScreen(
                    title = "Séries & Entretenimento",
                    subtitle = "Canais identificados como séries e entretenimento",
                    channels = state.channels.filter(::isSeriesChannel),
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
                AppScreen.SPORTS -> CuratedScreen(
                    title = "Esportes",
                    subtitle = "Canais e programação esportiva identificados no catálogo e no EPG",
                    channels = state.channels.filter { channel ->
                        isSportsChannel(channel, state.programs[channel.id])
                    },
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
                AppScreen.GUIDE -> GuideScreen(state, controller::select)
                AppScreen.FAVORITES -> CuratedScreen(
                    title = "Minha TV",
                    subtitle = "Seus canais favoritos",
                    channels = state.channels.filter { it.id in state.favorites },
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
                AppScreen.SEARCH -> SearchScreen(state, controller::select)
                AppScreen.SOURCES -> SourcesScreen(state, controller)
                AppScreen.DIAGNOSTICS -> DiagnosticsScreen(controller)
                AppScreen.WATCH -> Unit
            }
        }
    }
}

@Composable
private fun NavRail(
    selected: AppScreen,
    onNavigate: (AppScreen) -> Unit
) {
    val items = listOf(
        AppScreen.HOME to "Início",
        AppScreen.LIVE to "Ao vivo",
        AppScreen.MOVIES to "Filmes",
        AppScreen.SERIES to "Séries",
        AppScreen.SPORTS to "Esportes",
        AppScreen.GUIDE to "Guia",
        AppScreen.SEARCH to "Buscar",
        AppScreen.FAVORITES to "Minha TV",
        AppScreen.SOURCES to "Fontes"
    )

    Column(
        modifier = Modifier
            .width(194.dp)
            .fillMaxHeight()
            .background(Color(0xFF06090D))
            .padding(horizontal = 18.dp, vertical = 26.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Text(
            "S▶",
            color = SanchesColors.Accent,
            fontSize = 31.sp,
            fontWeight = FontWeight.Black
        )
        Text(
            "SANCHES",
            color = SanchesColors.PrimaryText,
            fontSize = 14.sp,
            fontWeight = FontWeight.Bold,
            letterSpacing = 2.sp
        )
        Text(
            "TV",
            color = SanchesColors.Accent,
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold,
            letterSpacing = 3.sp
        )
        Spacer(Modifier.height(18.dp))

        items.forEach { (screen, label) ->
            NavItem(
                label = label,
                selected = selected == screen,
                onClick = { onNavigate(screen) }
            )
        }

        Spacer(Modifier.weight(1f))

        NavItem(
            label = "Diagnóstico",
            selected = selected == AppScreen.DIAGNOSTICS,
            onClick = { onNavigate(AppScreen.DIAGNOSTICS) }
        )
    }
}

@Composable
private fun NavItem(
    label: String,
    selected: Boolean,
    onClick: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }
    val scale by animateFloatAsState(
        targetValue = if (focused) 1.04f else 1f,
        label = "navScale"
    )

    val background = when {
        focused -> SanchesColors.Focus
        selected -> SanchesColors.SurfaceStrong
        else -> Color.Transparent
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(46.dp)
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
            }
            .clip(RoundedCornerShape(14.dp))
            .background(background)
            .onFocusChanged { focused = it.isFocused }
            .clickable(onClick = onClick)
            .focusable()
            .padding(horizontal = 13.dp),
        contentAlignment = Alignment.CenterStart
    ) {
        Text(
            label,
            color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
            fontSize = 15.sp,
            fontWeight = FontWeight.SemiBold
        )
    }
}

@Composable
private fun HomeScreen(
    state: AppUiState,
    controller: ZappController
) {
    val hero = state.currentChannel ?: state.channels.firstOrNull()
    val program = hero?.let { state.programs[it.id] }
    val rankedNow = remember(
        state.channels,
        state.favorites,
        state.recentChannelIds,
        state.mostWatchedIds,
        state.programs
    ) {
        HomeChannelRanker.rank(
            channels = state.channels,
            favorites = state.favorites,
            recentIds = state.recentChannelIds,
            mostWatchedIds = state.mostWatchedIds,
            programs = state.programs
        ).take(14)
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 34.dp, vertical = 28.dp),
        verticalArrangement = Arrangement.spacedBy(20.dp)
    ) {
        item {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        "SANCHESTV",
                        color = SanchesColors.PrimaryText,
                        fontSize = 32.sp,
                        fontWeight = FontWeight.Black,
                        letterSpacing = 2.sp
                    )
                    Text(
                        state.onlineStatus,
                        color = SanchesColors.SecondaryText,
                        fontSize = 14.sp
                    )
                }

                Text(
                    SimpleDateFormat("HH:mm", Locale("pt", "BR")).format(Date()),
                    color = SanchesColors.SecondaryText,
                    fontSize = 18.sp
                )
            }
        }

        item {
            HeroCard(
                channel = hero,
                program = program,
                onWatch = {
                    if (hero != null) controller.select(hero)
                    else controller.open(AppScreen.LIVE)
                }
            )
        }

        item {
            SectionTitle(
                title = "Agora na TV",
                subtitle = "\${state.channels.size} canais agregados"
            )
            Spacer(Modifier.height(12.dp))
            ChannelRail(
                channels = state.channels.take(14),
                programs = state.programs,
                favorites = state.favorites,
                onSelect = controller::select,
                onFavorite = controller::toggleFavorite
            )
        }

        item {
            val recent = state.recentChannelIds
                .mapNotNull { id -> state.channels.firstOrNull { it.id == id } }
                .take(12)
            if (recent.isNotEmpty()) {
                SectionTitle("Continuar assistindo", "Canais vistos recentemente")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = recent,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }

        item {
            val mostWatched = state.mostWatchedIds
                .mapNotNull { id -> state.channels.firstOrNull { it.id == id } }
                .take(12)
            if (mostWatched.isNotEmpty()) {
                SectionTitle("Mais assistidos", "Baseado no seu uso neste dispositivo")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = mostWatched,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }

        item {
            val now = System.currentTimeMillis()
            val upcomingIds = state.schedule.entries
                .mapNotNull { (channelId, slots) ->
                    slots.firstOrNull { slot ->
                        slot.startMillis in (now + 1)..(now + 45L * 60L * 1000L)
                    }?.let { channelId to it.startMillis }
                }
                .sortedBy { it.second }
                .map { it.first }
                .distinct()
                .take(12)
            val upcomingChannels = upcomingIds.mapNotNull { id ->
                state.channels.firstOrNull { it.id == id }
            }

            if (upcomingChannels.isNotEmpty()) {
                SectionTitle("Começando em breve", "Programação prevista nos próximos 45 minutos")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = upcomingChannels,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }

        item {
            val favorites = state.channels.filter { it.id in state.favorites }.take(12)
            if (favorites.isNotEmpty()) {
                SectionTitle("Minha TV", "Favoritos")
                Spacer(Modifier.height(12.dp))
                ChannelRail(
                    channels = favorites,
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
            }
        }
    }
}

