@Composable
private fun LiveScreen(
    state: AppUiState,
    controller: ZappController
) {
    val categories = remember(state.channels) {
        state.channels
            .map { it.category.ifBlank { "TV" } }
            .distinct()
            .sorted()
    }

    var selectedCategory by remember { mutableStateOf<String?>(null) }

    val filtered = if (selectedCategory == null) {
        state.channels
    } else {
        state.channels.filter { it.category == selectedCategory }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 32.dp, vertical = 26.dp)
    ) {
        SectionTitle("Ao vivo", "\${filtered.size} canais")
        Spacer(Modifier.height(14.dp))

        LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            item {
                FilterChip(
                    label = "Todos",
                    selected = selectedCategory == null,
                    onClick = { selectedCategory = null }
                )
            }

            items(categories.take(50)) { category ->
                FilterChip(
                    label = category,
                    selected = selectedCategory == category,
                    onClick = { selectedCategory = category }
                )
            }
        }

        Spacer(Modifier.height(16.dp))

        ChannelList(
            channels = filtered,
            programs = state.programs,
            favorites = state.favorites,
            onSelect = controller::select,
            onFavorite = controller::toggleFavorite
        )
    }
}

@Composable
private fun MoviesScreen(controller: ZappController) {
    val context = LocalContext.current
    val engine = remember { InfiniteCinemaEngine(context) }
    val scope = rememberCoroutineScope()

    var movies by remember { mutableStateOf<List<VodItem>>(emptyList()) }
    var searchResults by remember { mutableStateOf<List<VodItem>>(emptyList()) }
    var page by remember { mutableIntStateOf(1) }
    var providerRevision by remember { mutableIntStateOf(0) }
    var loading by remember { mutableStateOf(true) }
    var searching by remember { mutableStateOf(false) }
    var status by remember { mutableStateOf("Inicializando Infinite Cinema…") }
    var query by remember { mutableStateOf("") }
    var selectedCatalog by remember { mutableStateOf("Todos") }
    var selectedMovie by remember { mutableStateOf<VodItem?>(null) }
    var resolvingId by remember { mutableStateOf<String?>(null) }
    var canLoadMore by remember { mutableStateOf(true) }
    var indexedCount by remember { mutableIntStateOf(0) }
    var playableCount by remember { mutableIntStateOf(0) }
    var ptSubtitleCount by remember { mutableIntStateOf(0) }
    var providerCount by remember { mutableIntStateOf(0) }
    var providerStatuses by remember { mutableStateOf(engine.providerStatus()) }

    val initialConfig = remember { engine.providerConfig() }
    var europeanaKey by remember { mutableStateOf(initialConfig.europeanaKey) }
    var dplaKey by remember { mutableStateOf(initialConfig.dplaKey) }

    LaunchedEffect(page, providerRevision) {
        loading = true
        val loaded = withContext(Dispatchers.IO) {
            engine.loadPage(page)
        }
        movies = MovieIdentityResolver.merge(movies + loaded.movies)
        canLoadMore = loaded.canLoadMore
        indexedCount = loaded.indexedCount
        playableCount = loaded.playableCount
        ptSubtitleCount = loaded.portugueseSubtitleCount
        providerCount = loaded.providerCount
        providerStatuses = engine.providerStatus()
        status = "${movies.size} nesta sessão • ${loaded.indexedCount} indexados • " +
            "${loaded.providerCount} provedores ativos"
        loading = false
    }

    LaunchedEffect(query) {
        val q = query.trim()
        if (q.length < 2) {
            searchResults = emptyList()
            searching = false
            return@LaunchedEffect
        }

        delay(450)
        if (q != query.trim()) return@LaunchedEffect
        searching = true
        val result = withContext(Dispatchers.IO) {
            engine.search(q)
        }
        searchResults = result.movies
        indexedCount = result.indexedCount
        playableCount = result.playableCount
        ptSubtitleCount = result.portugueseSubtitleCount
        providerCount = result.providerCount
        status = result.status
        searching = false
    }

    selectedMovie?.let { movie ->
        VodPlayerSurface(
            item = movie,
            onBack = { selectedMovie = null }
        )
        return
    }

    val sourceList = if (query.trim().length >= 2) searchResults else movies

    val catalogs = remember(sourceList) {
        listOf("Todos") + sourceList.map(VodItem::catalog)
            .filter(String::isNotBlank)
            .distinct()
            .sorted()
    }

    val visible = remember(sourceList, selectedCatalog) {
        sourceList.filter { item ->
            selectedCatalog == "Todos" || item.catalog == selectedCatalog
        }
    }

    fun play(item: VodItem) {
        if (resolvingId != null) return
        scope.launch {
            resolvingId = item.id
            status = "Preparando ${item.title}…"
            val resolved = withContext(Dispatchers.IO) {
                engine.resolve(item)
            }
            resolvingId = null
            if (resolved.playable) {
                selectedMovie = resolved
                status = if (resolved.subtitles.isNotEmpty()) {
                    "Filme pronto • ${resolved.subtitles.size} legenda(s)"
                } else {
                    "Filme pronto • faixas embutidas serão detectadas pelo Media3"
                }
            } else {
                status = if (!resolved.detailUrl.isNullOrBlank()) {
                    "Registro indexado • sem mídia direta autorizada/compatível"
                } else {
                    "Nenhuma mídia direta compatível foi encontrada"
                }
            }
        }
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 30.dp, vertical = 24.dp),
        verticalArrangement = Arrangement.spacedBy(18.dp)
    ) {
        item {
            SectionTitle(
                title = "Infinite Cinema",
                subtitle = "Internet Archive • Wikimedia • LOC • NASA • Europeana • DPLA"
            )
            Spacer(Modifier.height(10.dp))
            Text(
                status,
                color = if (loading || searching) SanchesColors.Accent
                else SanchesColors.SecondaryText,
                fontSize = 13.sp
            )
            Spacer(Modifier.height(7.dp))
            Text(
                "Índice: ${indexedCount} • Reproduzíveis: ${playableCount} • " +
                    "Com legenda PT: ${ptSubtitleCount} • Provedores ativos: ${providerCount}",
                color = SanchesColors.Muted,
                fontSize = 11.sp
            )
        }

        item {
            OutlinedTextField(
                value = query,
                onValueChange = {
                    query = it
                    selectedCatalog = "Todos"
                },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                label = {
                    Text("Busca universal: título, gênero, ano, instituição ou fonte")
                }
            )
        }

        item {
            LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                items(catalogs) { catalog ->
                    MovieFilterChip(
                        label = catalog,
                        selected = selectedCatalog == catalog,
                        onClick = { selectedCatalog = catalog }
                    )
                }
            }
        }

        if (visible.isEmpty() && !loading && !searching) {
            item { EmptyState("Nenhum filme encontrado com esse filtro") }
        } else {
            items(visible.chunked(5)) { row ->
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    row.forEach { movie ->
                        MoviePosterCard(
                            item = movie,
                            busy = resolvingId == movie.id,
                            onClick = { play(movie) }
                        )
                    }
                    repeat((5 - row.size).coerceAtLeast(0)) {
                        Spacer(Modifier.width(158.dp))
                    }
                }
            }
        }

        item {
            if (loading || searching) {
                Text(
                    if (searching) "Buscando em todos os provedores…" else "Descobrindo novos títulos…",
                    color = SanchesColors.Accent,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                )
            } else if (query.isBlank() && canLoadMore) {
                ActionButton(label = "Descobrir mais filmes") {
                    page += 1
                }
            }
        }

        item {
            SectionTitle(
                title = "Provedores de catálogo",
                subtitle = "Europeana e DPLA exigem chave gratuita do próprio serviço"
            )
            Spacer(Modifier.height(10.dp))
            providerStatuses.forEach { provider ->
                Text(
                    (if (provider.enabled) "● " else "○ ") + provider.name +
                        if (provider.requiresKey && !provider.enabled) " • chave necessária" else "",
                    color = if (provider.enabled) SanchesColors.SecondaryText else SanchesColors.Muted,
                    fontSize = 11.sp
                )
            }
            Spacer(Modifier.height(12.dp))

            OutlinedTextField(
                value = europeanaKey,
                onValueChange = { europeanaKey = it },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                label = { Text("Europeana API key (opcional)") }
            )
            Spacer(Modifier.height(8.dp))
            OutlinedTextField(
                value = dplaKey,
                onValueChange = { dplaKey = it },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                label = { Text("DPLA API key (opcional)") }
            )
            Spacer(Modifier.height(10.dp))
            ActionButton(label = "Salvar e ativar provedores") {
                engine.saveEuropeanaKey(europeanaKey)
                engine.saveDplaKey(dplaKey)
                providerStatuses = engine.providerStatus()
                providerRevision += 1
                status = "Configuração salva no dispositivo • atualizando provedores"
            }
        }

        item {
            Text(
                "O Infinite Cinema indexa metadados de acervos públicos/licenciados e só libera " +
                    "reprodução direta quando existe mídia compatível e uma base de direitos adequada. " +
                    "Registros sem mídia direta permanecem pesquisáveis sem serem apresentados como streaming.",
                color = SanchesColors.Muted,
                fontSize = 10.sp
            )
        }
    }
}

@Composable
private fun MovieFilterChip(
    label: String,
    selected: Boolean,
    onClick: () -> Unit
) {
