                    Text(
                        healthText,
                        color = if (health?.isHealthy == true) SanchesColors.Accent else SanchesColors.Muted,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Black
                    )

                    if (source.id.startsWith("user-")) {
                        Spacer(Modifier.width(10.dp))
                        FilterChip("Remover", false) {
                            controller.removeUserSource(source.id)
                        }
                    }
                }
            }
        }

        Spacer(Modifier.height(12.dp))

        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            ActionButton("Atualizar agora") {
                controller.refreshOnline(force = true, announce = true)
            }
            ActionButton(
                if (controller.startInLastChannel) "Abrir em: último canal" else "Abrir em: Início"
            ) {
                controller.toggleStartInLastChannel()
            }
        }
    }
