private fun isMovieChannel(channel: Channel): Boolean {
    val value = ChannelResolver.normalize("\${channel.category} \${channel.name}")
    return listOf("MOVIE", "FILME", "CINEMA", "FILMS")
        .any { token -> value.contains(token) }
}

private fun isSeriesChannel(channel: Channel): Boolean {
    val value = ChannelResolver.normalize("\${channel.category} \${channel.name}")
    return listOf("SERIE", "SERIES", "ENTERTAINMENT", "ENTRETENIMENTO")
        .any { token -> value.contains(token) }
}

private fun isSportsChannel(channel: Channel, program: ProgramInfo?): Boolean {
    val value = ChannelResolver.normalize(
        listOf(
            channel.category,
            channel.name,
            program?.title.orEmpty(),
            program?.subtitle.orEmpty()
        ).joinToString(" ")
    )

    return listOf(
        "ESPORTE", "SPORT", "FUTEBOL", "SOCCER", "BASQUETE", "BASKET",
        "NBA", "NBB", "TENIS", "TENNIS", "VOLEI", "VOLLEY", "MMA", "UFC",
        "FORMULA", "MOTOGP", "NFL"
    ).any(value::contains)
}

private fun programTime(program: ProgramInfo?): String? {
    val start = program?.startMillis ?: return null
    val end = program.endMillis ?: return null
    return "\${formatTime(start)} – \${formatTime(end)}"
}

private fun nextProgramTime(program: ProgramInfo?): String? =
    program?.nextStartMillis?.let(::formatTime)

private fun formatTime(value: Long): String =
    SimpleDateFormat("HH:mm", Locale("pt", "BR")).format(Date(value))

private fun formatDateTime(value: Long): String =
    SimpleDateFormat("dd/MM HH:mm", Locale("pt", "BR")).format(Date(value))

