@Composable
fun QuickGuideOverlay(
    state: AppUiState,
    onSelect: (Channel) -> Unit,
    onFavorite: (Channel) -> Unit,
    onClose: () -> Unit
) {
    var section by remember { mutableStateOf("Recentes") }
    val requester = remember { FocusRequester() }

    val channels = when (section) {
        "Favoritos" -> state.channels.filter { it.id in state.favorites }
        "Recentes" -> quickByIds(state.channels, state.recentChannelIds)
        "Brasil" -> state.channels.filter(ChannelClassifier::isBrazil)
        "Esportes" -> state.channels.filter { ChannelClassifier.category(it) == "Esportes" }
        "Notícias" -> state.channels.filter { ChannelClassifier.category(it) == "Notícias" }
        else -> state.channels
    }.take(100)

    LaunchedEffect(section, channels.firstOrNull()?.id) {
        if (channels.isNotEmpty()) {
            delay(100)
            runCatching { requester.requestFocus() }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(0.55f)
            .background(Color(0xF205080C))
            .padding(horizontal = 30.dp, vertical = 17.dp)
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                "CANAIS",
                color = SanchesColors.PrimaryText,
                fontSize = 20.sp,
                fontWeight = FontWeight.Black
            )

            Spacer(Modifier.width(14.dp))

            listOf("Recentes", "Favoritos", "Brasil", "Esportes", "Notícias", "Todos").forEach { item ->
                QuickChip(
                    label = item,
                    selected = section == item,
                    onClick = { section = item }
                )
                Spacer(Modifier.width(6.dp))
            }

            Spacer(Modifier.weight(1f))

            Text(
                "BACK fecha",
                color = SanchesColors.Muted,
                fontSize = 11.sp,
                modifier = Modifier.clickable(onClick = onClose)
            )
        }

        Spacer(Modifier.height(11.dp))

        if (channels.isEmpty()) {
            Text(
                "Ainda não há canais nesta seção.",
                color = SanchesColors.SecondaryText,
                fontSize = 14.sp,
                modifier = Modifier.padding(20.dp)
            )
        } else {
            LazyColumn(verticalArrangement = Arrangement.spacedBy(5.dp)) {
                items(channels, key = { it.id }) { channel ->
                    QuickRow(
                        channel = channel,
                        program = state.programs[channel.id],
                        favorite = channel.id in state.favorites,
                        focusFirst = channel.id == channels.first().id,
                        requester = requester,
                        onSelect = { onSelect(channel) },
                        onFavorite = { onFavorite(channel) }
                    )
                }
            }
        }
    }
}

