package com.mukasanches.zapptv.playback

object PlaybackRecoveryPolicy {
    fun sanitize(candidates: List<String>): List<String> =
        candidates
            .map(String::trim)
            .filter { it.startsWith("https://", true) || it.startsWith("http://", true) }
            .distinct()

    fun nextCandidate(current: Int, size: Int): Int? =
        (current + 1).takeIf { size > 0 && it < size }

    fun retryDelay(attempt: Int): Long {
        val safe = attempt.coerceIn(0, 4)
        return (1000L shl safe).coerceAtMost(8000L)
    }
}

package com.mukasanches.zapptv.playback

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class PlaybackRecoveryPolicyTest {
    @Test
    fun sanitizesAndDeduplicatesCandidates() {
        val result = PlaybackRecoveryPolicy.sanitize(
            listOf(" https://a.test/live.m3u8 ", "ftp://bad", "https://a.test/live.m3u8", "http://b.test/live")
        )
        assertEquals(listOf("https://a.test/live.m3u8", "http://b.test/live"), result)
    }

    @Test
    fun movesOnlyWithinBounds() {
        assertEquals(1, PlaybackRecoveryPolicy.nextCandidate(0, 2))
        assertNull(PlaybackRecoveryPolicy.nextCandidate(1, 2))
    }

    @Test
    fun retryDelayIsBounded() {
        assertEquals(1000L, PlaybackRecoveryPolicy.retryDelay(0))
        assertEquals(2000L, PlaybackRecoveryPolicy.retryDelay(1))
        assertEquals(8000L, PlaybackRecoveryPolicy.retryDelay(10))
    }
}

package com.mukasanches.zapptv.data

import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo

object HomeChannelRanker {
    fun rank(
        channels: List<Channel>,
        favorites: Set<String>,
        recentIds: List<String>,
        mostWatchedIds: List<String>,
        programs: Map<String, ProgramInfo>
    ): List<Channel> {
        val recentRank = recentIds.withIndex().associate { it.value to it.index }
        val watchedRank = mostWatchedIds.withIndex().associate { it.value to it.index }

        return channels
            .distinctBy(Channel::id)
            .sortedWith(
                compareByDescending<Channel> { channel ->
                    var score = 0
                    if (channel.id in favorites) score += 1000
                    recentRank[channel.id]?.let { score += (300 - it * 10).coerceAtLeast(0) }
                    watchedRank[channel.id]?.let { score += (200 - it * 5).coerceAtLeast(0) }
                    if (programs[channel.id] != null) score += 40
                    if (programs[channel.id]?.nextTitle != null) score += 10
                    score
                }.thenBy { ChannelResolver.normalize(it.name) }
            )
    }
}

