package com.mukasanches.zapptv.data

import android.content.Context
import okhttp3.Cache
import okhttp3.OkHttpClient
import okhttp3.Request
import java.io.BufferedInputStream
import java.io.File
import java.io.FileOutputStream
import java.util.concurrent.TimeUnit
import java.util.zip.GZIPInputStream

enum class HttpDownloadResult {
    UPDATED,
    NOT_MODIFIED,
    FAILED
}

class HttpDownloadEngine(context: Context) {
    private val appContext = context.applicationContext
    private val prefs = appContext.getSharedPreferences("sanchestv-http-meta", Context.MODE_PRIVATE)

    private val client: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .cache(Cache(File(appContext.cacheDir, "sanchestv-http"), HTTP_CACHE_BYTES))
            .connectTimeout(CONNECT_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .readTimeout(READ_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .followRedirects(true)
            .followSslRedirects(true)
            .retryOnConnectionFailure(true)
            .build()
    }

    fun download(
        url: String,
        target: File,
        maxBytes: Long,
        validator: ((File) -> Boolean)? = null
    ): HttpDownloadResult {
        if (!url.startsWith("https://", ignoreCase = true)) {
            return HttpDownloadResult.FAILED
        }

        val requestBuilder = Request.Builder()
            .url(url)
            .header("User-Agent", USER_AGENT)
            .header("Accept", "*/*")

        prefs.getString(metaKey(url, "etag"), null)
            ?.takeIf(String::isNotBlank)
            ?.let { requestBuilder.header("If-None-Match", it) }

        prefs.getString(metaKey(url, "last_modified"), null)
            ?.takeIf(String::isNotBlank)
            ?.let { requestBuilder.header("If-Modified-Since", it) }

        val temp = File(target.parentFile, "${target.name}.tmp")

        return runCatching {
            client.newCall(requestBuilder.build()).execute().use { response ->
                if (response.code == 304 && target.isFile && target.length() > 0L) {
                    target.setLastModified(System.currentTimeMillis())
                    return@use HttpDownloadResult.NOT_MODIFIED
                }

                if (!response.isSuccessful) {
                    return@use HttpDownloadResult.FAILED
                }

                val body = response.body
                val raw = BufferedInputStream(body.byteStream())
                raw.mark(4)
                val first = raw.read()
                val second = raw.read()
                raw.reset()

                val input = if (first == GZIP_MAGIC_1 && second == GZIP_MAGIC_2) {
                    GZIPInputStream(raw)
                } else {
                    raw
                }

                FileOutputStream(temp).use { output ->
                    input.use { source ->
                        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
                        var total = 0L
                        while (true) {
                            val read = source.read(buffer)
                            if (read <= 0) break
                            total += read
                            require(total <= maxBytes) {
                                "Resposta excedeu o limite seguro"
                            }
                            output.write(buffer, 0, read)
                        }
                        output.fd.sync()
                    }
                }

                require(temp.length() > 0L) { "Resposta vazia" }
                require(validator?.invoke(temp) != false) { "Conteúdo inválido" }

                if (!temp.renameTo(target)) {
                    temp.copyTo(target, overwrite = true)
                    temp.delete()
                }
                target.setLastModified(System.currentTimeMillis())

                prefs.edit().apply {
                    response.header("ETag")?.let {
                        putString(metaKey(url, "etag"), it)
                    }
                    response.header("Last-Modified")?.let {
                        putString(metaKey(url, "last_modified"), it)
                    }
                }.apply()

                HttpDownloadResult.UPDATED
            }
        }.getOrElse {
            temp.delete()
            HttpDownloadResult.FAILED
        }
    }

    fun versionToken(url: String): String? =
        prefs.getString(metaKey(url, "etag"), null)
            ?: prefs.getString(metaKey(url, "last_modified"), null)

    private fun metaKey(url: String, suffix: String): String =
        url.hashCode().toUInt().toString(16) + "_" + suffix

    companion object {
        private const val USER_AGENT = "SANCHESTV/2.8 (Android TV)"
        private const val CONNECT_TIMEOUT_SECONDS = 5L
        private const val READ_TIMEOUT_SECONDS = 22L
        private const val CALL_TIMEOUT_SECONDS = 35L
        private const val HTTP_CACHE_BYTES = 48L * 1024L * 1024L
        private const val GZIP_MAGIC_1 = 0x1f
        private const val GZIP_MAGIC_2 = 0x8b
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo
import com.mukasanches.zapptv.model.ProgramSlot
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.util.zip.GZIPInputStream
import java.util.zip.GZIPOutputStream

class EpgDiskCache(context: Context) {
    private val file = File(context.filesDir, "sanchestv-cache/epg-schedule-v3.json.gz")

    fun load(
        channels: List<Channel>,
        sourceVersion: String,
        now: Long = System.currentTimeMillis()
    ): EpgSchedule? {
        if (!file.isFile || file.length() <= 0L) return null

        return runCatching {
            val root = GZIPInputStream(file.inputStream().buffered()).use { input ->
                JSONObject(input.reader(Charsets.UTF_8).readText())
            }

            if (root.optInt("schema", 0) != SCHEMA_VERSION) return@runCatching null
            if (root.optString("sourceVersion") != sourceVersion) return@runCatching null

            val allowed = channels.asSequence().map(Channel::id).toHashSet()
            val timeline = linkedMapOf<String, MutableList<ProgramSlot>>()
            val items = root.optJSONArray("items") ?: JSONArray()

            for (index in 0 until items.length()) {
                val json = items.optJSONObject(index) ?: continue
                val channelId = json.optString("c")
                if (channelId !in allowed) continue

                val start = json.optLong("s", Long.MIN_VALUE)
                val end = json.optLong("e", Long.MIN_VALUE)
                if (start == Long.MIN_VALUE || end == Long.MIN_VALUE || end <= now - PAST_GRACE_MS) {
                    continue
                }

                timeline.getOrPut(channelId) { mutableListOf() }.add(
                    ProgramSlot(
                        channelId = channelId,
                        title = json.optString("t").ifBlank { "Ao vivo" },
                        subtitle = json.optString("u").takeIf(String::isNotBlank),
                        description = json.optString("d").takeIf(String::isNotBlank),
                        startMillis = start,
                        endMillis = end
                    )
                )
            }

            scheduleFromTimeline(timeline, now)
        }.getOrNull()
    }

    fun save(schedule: EpgSchedule, sourceVersion: String) {
        runCatching {
            file.parentFile?.mkdirs()

            val items = JSONArray()
            schedule.timeline.values
                .flatten()
                .sortedWith(compareBy<ProgramSlot> { it.channelId }.thenBy { it.startMillis })
                .forEach { slot ->
                    val json = JSONObject()
                        .put("c", slot.channelId)
                        .put("t", slot.title)
                        .put("s", slot.startMillis)
                        .put("e", slot.endMillis)

                    slot.subtitle?.let { json.put("u", it) }
                    slot.description?.let { json.put("d", it) }
                    items.put(json)
                }

            val root = JSONObject()
                .put("schema", SCHEMA_VERSION)
                .put("sourceVersion", sourceVersion)
                .put("generatedAt", System.currentTimeMillis())
                .put("items", items)

            val temp = File(file.parentFile, file.name + ".tmp")
            GZIPOutputStream(temp.outputStream().buffered()).use { output ->
                output.writer(Charsets.UTF_8).use { writer ->
                    writer.write(root.toString())
                }
            }

            if (!temp.renameTo(file)) {
                temp.copyTo(file, overwrite = true)
                temp.delete()
            }
        }
    }

    private fun scheduleFromTimeline(
        source: Map<String, List<ProgramSlot>>,
        now: Long
    ): EpgSchedule {
        val timeline = source.mapValues { (_, values) ->
            values
                .distinctBy { "${it.startMillis}:${it.endMillis}:${it.title}" }
                .sortedBy(ProgramSlot::startMillis)
                .take(MAX_PROGRAMS_PER_CHANNEL)
        }

        val current = linkedMapOf<String, ProgramInfo>()
        timeline.forEach { (channelId, programs) ->
            val live = programs.lastOrNull { it.isLive(now) } ?: return@forEach
            val next = programs.firstOrNull { it.startMillis >= live.endMillis }
                ?: programs.firstOrNull { it.startMillis > now }

            current[channelId] = ProgramInfo(
                channelId = channelId,
                title = live.title,
                subtitle = live.subtitle,
                description = live.description,
                startMillis = live.startMillis,
                endMillis = live.endMillis,
                nextTitle = next?.title,
                nextStartMillis = next?.startMillis,
                nextEndMillis = next?.endMillis
            )
        }

        return EpgSchedule(
            currentPrograms = current,
            timeline = timeline
        )
    }

    companion object {
        private const val SCHEMA_VERSION = 3
        private const val PAST_GRACE_MS = 2L * 60L * 60L * 1000L
        private const val MAX_PROGRAMS_PER_CHANNEL = 336
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import com.mukasanches.zapptv.BuildConfig
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import java.security.MessageDigest
import java.util.concurrent.TimeUnit

data class UpdateCheck(
    val available: Boolean = false,
    val latestVersion: String? = null,
    val apkUrl: String? = null,
    val sha256: String? = null,
    val notes: String? = null,
    val status: String = "Atualização não verificada"
)

class UpdateRepository(context: Context) {
    private val appContext = context.applicationContext

    private val client = OkHttpClient.Builder()
        .connectTimeout(5, TimeUnit.SECONDS)
        .readTimeout(20, TimeUnit.SECONDS)
        .callTimeout(90, TimeUnit.SECONDS)
        .retryOnConnectionFailure(true)
        .build()

    fun check(): UpdateCheck {
        val request = Request.Builder()
            .url(RELEASE_MANIFEST_URL)
            .header("User-Agent", "SANCHESTV/${BuildConfig.VERSION_NAME}")
            .header("Cache-Control", "no-cache")
            .build()

        return runCatching {
            client.newCall(request).execute().use { response ->
                if (!response.isSuccessful) {
                    return@use UpdateCheck(status = "Servidor de atualização indisponível")
                }

                val body = response.body.string()
                val json = JSONObject(body)
                val versionCode = json.optInt("versionCode", 0)
                val versionName = json.optString("versionName").takeIf(String::isNotBlank)
                val apkUrl = json.optString("apkUrl").takeIf { it.startsWith("https://") }
                val sha256 = json.optString("sha256")
                    .trim()
                    .lowercase()
                    .takeIf { it.matches(Regex("[0-9a-f]{64}")) }
                val notes = json.optString("notes").takeIf(String::isNotBlank)

                val available =
                    versionCode > BuildConfig.VERSION_CODE &&
                        apkUrl != null &&
                        sha256 != null

                UpdateCheck(
                    available = available,
                    latestVersion = versionName,
                    apkUrl = apkUrl,
                    sha256 = sha256,
                    notes = notes,
                    status = if (available) {
                        "SANCHESTV ${versionName ?: versionCode} disponível"
                    } else {
                        "Você está na versão mais recente"
                    }
                )
            }
        }.getOrElse {
            UpdateCheck(status = "Não foi possível verificar atualizações")
        }
    }

    fun downloadVerified(apkUrl: String, expectedSha256: String): File? {
        if (!apkUrl.startsWith("https://", ignoreCase = true)) return null
        val expected = expectedSha256.trim().lowercase()
        if (!expected.matches(Regex("[0-9a-f]{64}"))) return null

        val directory = File(appContext.cacheDir, "updates").apply { mkdirs() }
        val temp = File(directory, "sanchestv-update.apk.part")
        val output = File(directory, "sanchestv-update.apk")
        val digest = MessageDigest.getInstance("SHA-256")

        val request = Request.Builder()
            .url(apkUrl)
            .header("User-Agent", "SANCHESTV/${BuildConfig.VERSION_NAME}")
            .build()

        return runCatching {
            client.newCall(request).execute().use { response ->
                require(response.isSuccessful) { "HTTP ${response.code}" }
                val declaredLength = response.body.contentLength()
                require(declaredLength <= MAX_APK_BYTES || declaredLength < 0L) {
                    "APK excede limite seguro"
                }

                FileOutputStream(temp).use { sink ->
                    response.body.byteStream().use { source ->
                        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
                        var total = 0L
                        while (true) {
                            val count = source.read(buffer)
                            if (count <= 0) break
                            total += count
                            require(total <= MAX_APK_BYTES) { "APK excede limite seguro" }
                            digest.update(buffer, 0, count)
                            sink.write(buffer, 0, count)
                        }
                        sink.fd.sync()
                    }
                }

                val actual = digest.digest().joinToString("") { "%02x".format(it) }
                require(actual == expected) { "SHA-256 inválido" }
                require(temp.length() > 0L) { "APK vazio" }

                if (!temp.renameTo(output)) {
                    temp.copyTo(output, overwrite = true)
                    temp.delete()
                }
                output
            }
        }.getOrElse {
            temp.delete()
            null
        }
    }

    companion object {
        const val RELEASE_MANIFEST_URL =
            "https://sanchestv-release.onrender.com/release-manifest.json"
        private const val MAX_APK_BYTES = 300L * 1024L * 1024L
    }
}

package com.mukasanches.zapptv.platform

import android.annotation.SuppressLint
import android.content.Context
import android.net.Uri
import android.os.Build
import androidx.tvprovider.media.tv.PreviewChannel
import androidx.tvprovider.media.tv.PreviewChannelHelper
import androidx.tvprovider.media.tv.PreviewProgram
import androidx.tvprovider.media.tv.TvContractCompat
import com.mukasanches.zapptv.R
import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo

@SuppressLint("RestrictedApi")
class HomeChannelPublisher(context: Context) {
    private val appContext = context.applicationContext
    private val prefs = appContext.getSharedPreferences("sanchestv-home-provider", Context.MODE_PRIVATE)

    fun publish(
        channels: List<Channel>,
        programs: Map<String, ProgramInfo>,
        favorites: Set<String>,
        recentIds: List<String>
    ) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O || channels.isEmpty()) return

        val selected = selectChannels(channels, favorites, recentIds)
        if (selected.isEmpty()) return

        val signature = selected.joinToString("|") { channel ->
            val program = programs[channel.id]
            listOf(
                channel.id,
                channel.name,
                channel.logoUri.orEmpty(),
                program?.title.orEmpty(),
                program?.nextTitle.orEmpty()
            ).joinToString(":")
        }.hashCode().toString()

        if (prefs.getString(KEY_SIGNATURE, null) == signature) return

        runCatching {
            val helper = PreviewChannelHelper(appContext)
            val existing = runCatching { helper.allChannels }
                .getOrDefault(emptyList())
                .firstOrNull { it.internalProviderId == INTERNAL_CHANNEL_ID }

            val appLink = Uri.parse("sanchestv://home")
            val logo = Uri.parse(
                "android.resource://${appContext.packageName}/${R.mipmap.ic_launcher}"
            )

            val builder = if (existing == null) {
                PreviewChannel.Builder()
            } else {
                PreviewChannel.Builder(existing)
            }

            val channel = builder
                .setInternalProviderId(INTERNAL_CHANNEL_ID)
                .setDisplayName("SANCHESTV • Minha TV")
                .setDescription("Favoritos e canais recentes")
                .setAppLinkIntentUri(appLink)
                .setLogo(logo)
                .build()

            val channelId = if (existing == null) {
                helper.publishChannel(channel)
            } else {
                helper.updatePreviewChannel(existing.id, channel)
                existing.id
            }

            val programsUri = TvContractCompat.buildPreviewProgramsUriForChannel(channelId)
            appContext.contentResolver.delete(programsUri, null, null)

            selected.forEachIndexed { index, source ->
                val epg = programs[source.id]
                val description = buildList {
                    epg?.title?.takeIf(String::isNotBlank)?.let(::add)
                    epg?.nextTitle?.takeIf(String::isNotBlank)?.let {
                        add("A seguir: $it")
                    }
                    source.category.takeIf(String::isNotBlank)?.let(::add)
                }.joinToString(" • ")

                val programBuilder = PreviewProgram.Builder()
                    .setChannelId(channelId)
                    .setType(TvContractCompat.PreviewPrograms.TYPE_CLIP)
                    .setTitle(source.name)
                    .setDescription(description.ifBlank { "Ao vivo" })
                    .setIntentUri(
                        Uri.parse("sanchestv://channel/${Uri.encode(source.id)}")
                    )
                    .setInternalProviderId(source.id)
                    .setWeight(selected.size - index)
                    .setPosterArtAspectRatio(
                        TvContractCompat.PreviewPrograms.ASPECT_RATIO_16_9
                    )

                source.logoUri
                    ?.takeIf(String::isNotBlank)
                    ?.let { runCatching { Uri.parse(it) }.getOrNull() }
                    ?.let(programBuilder::setPosterArtUri)

                helper.publishPreviewProgram(programBuilder.build())
            }

            prefs.edit()
                .putString(KEY_SIGNATURE, signature)
                .putLong(KEY_LAST_PUBLISH, System.currentTimeMillis())
                .apply()
        }
    }

    private fun selectChannels(
        channels: List<Channel>,
        favorites: Set<String>,
        recentIds: List<String>
    ): List<Channel> {
        val byId = channels.associateBy(Channel::id)
        val result = linkedMapOf<String, Channel>()

        favorites.forEach { id -> byId[id]?.let { result[id] = it } }
        recentIds.forEach { id -> byId[id]?.let { result[id] = it } }

        if (result.isEmpty()) {
            channels.take(FALLBACK_CHANNELS).forEach { result[it.id] = it }
        }

        return result.values.take(MAX_PROGRAMS)
    }

    companion object {
        private const val INTERNAL_CHANNEL_ID = "sanchestv-my-tv-v1"
        private const val KEY_SIGNATURE = "content_signature"
        private const val KEY_LAST_PUBLISH = "last_publish"
        private const val MAX_PROGRAMS = 20
        private const val FALLBACK_CHANNELS = 12
    }
}

package com.mukasanches.zapptv.ui

import android.net.Uri
import androidx.activity.compose.BackHandler
