@Composable
fun VodPlayerSurface(
    item: VodItem,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    var captionsEnabled by remember(item.id) {
        mutableStateOf(item.subtitles.isNotEmpty())
    }
    var subtitleIndex by remember(item.id) { mutableStateOf(0) }
    var playbackStatus by remember(item.id) { mutableStateOf("Preparando…") }

    val player = remember(item.id) {
        ExoPlayer.Builder(context)
            .setRenderersFactory(
                DefaultRenderersFactory(context)
                    .setEnableDecoderFallback(true)
            )
            .build()
            .apply {
                playWhenReady = true
                setHandleAudioBecomingNoisy(true)
            }
    }

    BackHandler(onBack = onBack)

    LaunchedEffect(item.id, captionsEnabled, subtitleIndex) {
        val selected = item.subtitles.getOrNull(subtitleIndex)
        val textLanguages = buildList {
            selected?.language?.takeIf { it != "und" }?.let(::add)
            add("pt-BR")
            add("pt")
            add("en")
            add("es")
        }.distinct().toTypedArray()

        player.trackSelectionParameters = player.trackSelectionParameters
            .buildUpon()
            .setPreferredAudioLanguages("pt-BR", "pt", "en")
            .setPreferredTextLanguages(*textLanguages)
            .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, !captionsEnabled)
            .build()
    }

    DisposableEffect(player, item.id) {
        val listener = object : Player.Listener {
            override fun onPlaybackStateChanged(playbackState: Int) {
                playbackStatus = when (playbackState) {
                    Player.STATE_BUFFERING -> "Carregando…"
                    Player.STATE_READY -> "Reproduzindo"
                    Player.STATE_ENDED -> "Fim"
                    else -> playbackStatus
                }
            }

            override fun onPlayerError(error: androidx.media3.common.PlaybackException) {
                playbackStatus = "Falha na reprodução"
            }
        }
        player.addListener(listener)

        val playback = item.playbackUrl
        if (!playback.isNullOrBlank()) {
            val subtitles = item.subtitles.map { subtitle ->
                MediaItem.SubtitleConfiguration.Builder(Uri.parse(subtitle.uri))
                    .setMimeType(subtitle.mimeType)
                    .setLanguage(subtitle.language)
                    .setLabel(subtitle.label)
                    .setSelectionFlags(
                        if (subtitle.isDefault) C.SELECTION_FLAG_DEFAULT else 0
                    )
                    .build()
            }

            val mediaItem = MediaItem.Builder()
                .setMediaId(item.id)
                .setUri(playback)
                .setSubtitleConfigurations(subtitles)
                .build()

            player.setMediaItem(mediaItem)
            player.prepare()
            player.play()
        } else {
            playbackStatus = "Filme sem arquivo reproduzível"
        }

        onDispose {
            player.removeListener(listener)
            player.release()
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
    ) {
        AndroidView(
            factory = {
                PlayerView(it).apply {
                    useController = true
                    controllerAutoShow = false
                    controllerShowTimeoutMs = 4_000
                    resizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT
                    setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                    this.player = player
                    isFocusable = true
                    requestFocus()
                }
            },
            update = { it.player = player },
            modifier = Modifier.fillMaxSize()
        )

        Column(
            modifier = Modifier
                .align(Alignment.BottomStart)
                .fillMaxWidth()
                .background(
                    Brush.verticalGradient(
                        listOf(Color.Transparent, Color(0xF2070A0E))
                    )
                )
                .padding(horizontal = 34.dp, vertical = 24.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                item.title,
                color = Color.White,
                fontSize = 26.sp,
                fontWeight = FontWeight.Black
            )

            val metadata = buildList {
                item.year?.let(::add)
                item.catalog.takeIf(String::isNotBlank)?.let(::add)
                item.licenseName?.let(::add)
            }.joinToString(" • ")

            if (metadata.isNotBlank()) {
                Text(
                    metadata,
                    color = SanchesColors.SecondaryText,
                    fontSize = 12.sp
                )
            }

            Text(
                playbackStatus,
                color = SanchesColors.Muted,
                fontSize = 11.sp
            )

            Row(
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                val selectedSubtitle = item.subtitles.getOrNull(subtitleIndex)
                VodControlButton(
                    label = when {
                        !captionsEnabled -> "Legenda: desligada"
                        selectedSubtitle != null -> "Legenda: ${selectedSubtitle.label}"
                        else -> "Legenda: automática"
                    }
                ) {
                    if (item.subtitles.isEmpty()) {
                        captionsEnabled = !captionsEnabled
                    } else if (!captionsEnabled) {
                        subtitleIndex = 0
                        captionsEnabled = true
                    } else if (subtitleIndex < item.subtitles.lastIndex) {
                        subtitleIndex += 1
                    } else {
                        captionsEnabled = false
                        subtitleIndex = 0
                    }
                }

                Text(
                    if (item.subtitles.isEmpty()) {
                        "Faixas embutidas quando disponíveis"
                    } else {
                        "${item.subtitles.size} faixa(s) externa(s) • PT-BR priorizado"
                    },
                    color = SanchesColors.SecondaryText,
                    fontSize = 11.sp
                )

                Spacer(Modifier.weight(1f))

                VodControlButton(label = "Voltar") {
                    onBack()
                }
            }
        }
    }
}

@Composable
private fun VodControlButton(
    label: String,
    enabled: Boolean = true,
    onClick: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }

    Box(
        modifier = Modifier
            .height(42.dp)
            .clip(RoundedCornerShape(18.dp))
            .background(
                when {
                    !enabled -> Color(0xFF20262C)
                    focused -> SanchesColors.Focus
                    else -> SanchesColors.AccentStrong
                }
            )
            .onFocusChanged { focused = it.isFocused }
            .then(
                if (enabled) {
                    Modifier.clickable(onClick = onClick).focusable()
                } else {
                    Modifier
                }
            )
            .padding(horizontal = 16.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = when {
                !enabled -> SanchesColors.Muted
                focused -> SanchesColors.FocusText
                else -> Color.White
            },
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold
        )
    }
}

package com.mukasanches.zapptv.vod

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.coroutineScope
import okhttp3.Cache
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.net.URLEncoder
import java.util.concurrent.TimeUnit

class OpenMovieCatalogRepository(context: Context) {
    private val appContext = context.applicationContext
    private val client = OkHttpClient.Builder()
        .cache(Cache(File(appContext.cacheDir, "vod-http-cache"), 64L * 1024L * 1024L))
        .connectTimeout(6, TimeUnit.SECONDS)
        .readTimeout(15, TimeUnit.SECONDS)
        .callTimeout(25, TimeUnit.SECONDS)
        .retryOnConnectionFailure(true)
        .build()

    suspend fun loadPage(page: Int): VodCatalogState = coroutineScope {
        val safePage = page.coerceAtLeast(1)
        val archiveJobs = ARCHIVE_CATALOGS.map { source ->
            async(Dispatchers.IO) { runCatching { archivePage(source, safePage) }.getOrDefault(emptyList()) }
        }
        val commonsJobs = COMMONS_CATALOGS.map { source ->
            async(Dispatchers.IO) {
                runCatching { commonsPage(source, safePage) }.getOrDefault(emptyList())
            }
        }
        val locJobs = LOC_CATALOGS.map { source ->
            async(Dispatchers.IO) {
                runCatching { locPage(source, safePage) }.getOrDefault(emptyList())
            }
        }

        val combined = buildList {
            if (safePage == 1) addAll(OpenMovieFixtures.items)
            addAll(archiveJobs.awaitAll().flatten())
            addAll(commonsJobs.awaitAll().flatten())
            addAll(locJobs.awaitAll().flatten())
        }

        val deduped = MovieCatalogDeduplicator.deduplicate(combined)
        VodCatalogState(
            featured = deduped.filter { it.playable || it.id.startsWith("open:") }.take(18),
            movies = deduped,
            page = safePage,
            canLoadMore = deduped.isNotEmpty(),
            status = buildString {
                append(deduped.size)
                append(" filmes carregados • ")
                append(LOGICAL_CATALOG_COUNT)
                append(" catálogos públicos/livres")
            }
        )
    }

    suspend fun resolve(item: VodItem): VodItem =
        when {
            item.id.startsWith("ia:") -> archiveDetails(item)
            item.id.startsWith("commons:") -> commonsDetails(item)
            item.id.startsWith("loc:") -> locDetails(item)
            else -> item
        }

    private fun archivePage(source: ArchiveCatalog, page: Int): List<VodItem> {
        val query = encode(source.query)
        val url = buildString {
            append("https://archive.org/advancedsearch.php?q=")
            append(query)
            append("&fl%5B%5D=identifier")
            append("&fl%5B%5D=title")
            append("&fl%5B%5D=description")
            append("&fl%5B%5D=year")
            append("&fl%5B%5D=date")
            append("&fl%5B%5D=creator")
            append("&fl%5B%5D=subject")
            append("&fl%5B%5D=licenseurl")
            append("&fl%5B%5D=rights")
            append("&fl%5B%5D=downloads")
            append("&sort%5B%5D=downloads%20desc")
            append("&rows=")
            append(ARCHIVE_PAGE_SIZE)
            append("&page=")
            append(page)
            append("&output=json")
        }

        val root = getJson(url) ?: return emptyList()
        val docs = root.optJSONObject("response")?.optJSONArray("docs") ?: return emptyList()
        return buildList {
            for (i in 0 until docs.length()) {
                val doc = docs.optJSONObject(i) ?: continue
                val identifier = doc.optString("identifier").trim()
                val title = doc.optString("title").trim()
                if (identifier.isBlank() || title.isBlank()) continue
                val subjects = jsonStrings(doc.opt("subject"))
                val rights = jsonText(doc.opt("rights")).trim()
                val licenseUrl = jsonText(doc.opt("licenseurl")).trim()
                if (
                    source.requiresOpenRightsSignal &&
                    !ArchiveRightsPolicy.isOpen(rights, licenseUrl)
                ) continue

                add(
                    VodItem(
                        id = "ia:$identifier",
                        title = title,
                        overview = jsonText(doc.opt("description")),
                        posterUrl = "https://archive.org/services/img/${encodePath(identifier)}",
                        year = jsonText(doc.opt("year")).take(4).takeIf { it.length == 4 }
                            ?: jsonText(doc.opt("date")).take(4).takeIf { it.length == 4 },
                        genres = subjects.take(6),
                        language = "und",
                        playbackUrl = null,
                        source = "Internet Archive",
                        catalog = source.name,
                        detailUrl = "https://archive.org/details/${encodePath(identifier)}",
                        licenseName = rights.takeIf(String::isNotBlank)
                            ?: "Direitos informados no registro do item",
                        licenseUrl = licenseUrl.takeIf(String::isNotBlank),
                        attribution = jsonText(doc.opt("creator")).takeIf(String::isNotBlank)
                    )
                )
            }
        }
    }

    private fun archiveDetails(item: VodItem): VodItem {
        val identifier = item.id.removePrefix("ia:")
        val root = getJson("https://archive.org/metadata/${encodePath(identifier)}") ?: return item
        val files = root.optJSONArray("files") ?: return item
        val metadata = root.optJSONObject("metadata")
        val videos = mutableListOf<Pair<Int, String>>()
        val subtitles = mutableListOf<VodSubtitle>()

        for (i in 0 until files.length()) {
            val file = files.optJSONObject(i) ?: continue
            val name = file.optString("name").trim()
            if (name.isBlank()) continue
            val lower = name.lowercase()
            val url = "https://archive.org/download/${encodePath(identifier)}/${encodePath(name)}"

            if (VodSubtitleSupport.isSupportedFile(lower)) {
                VodSubtitleSupport.fromUrl(url)?.let(subtitles::add)
                continue
            }

            val score = videoScore(lower, file.optString("format"))
            if (score > 0) videos += score to url
        }

        val playback = videos.maxByOrNull { it.first }?.second
        val licenseUrl = metadata?.optString("licenseurl")?.takeIf(String::isNotBlank)
        val rights = metadata?.optString("rights")?.takeIf(String::isNotBlank)

        return item.copy(
            playbackUrl = playback,
            licenseUrl = licenseUrl ?: item.licenseUrl,
            licenseName = rights ?: item.licenseName,
            subtitles = VodSubtitleSupport.preferPortuguese(subtitles)
        )
    }

    private fun commonsPage(source: CommonsCatalog, page: Int): List<VodItem> {
        val offset = (page - 1) * COMMONS_PAGE_SIZE
        val search = encode(source.search)
        val url = "https://commons.wikimedia.org/w/api.php" +
            "?action=query&generator=search&gsrsearch=$search&gsrnamespace=6" +
            "&gsrlimit=$COMMONS_PAGE_SIZE&gsroffset=$offset" +
            "&prop=imageinfo&iiprop=url%7Cmime%7Cmediatype%7Cextmetadata" +
            "&format=json&origin=*"

        val root = getJson(url) ?: return emptyList()
        val pages = root.optJSONObject("query")?.optJSONObject("pages") ?: return emptyList()
        return buildList {
            pages.keys().forEach { key ->
                val pageObj = pages.optJSONObject(key) ?: return@forEach
                val info = pageObj.optJSONArray("imageinfo")?.optJSONObject(0) ?: return@forEach
                val mime = info.optString("mime")
                val mediaType = info.optString("mediatype")
                if (!mime.startsWith("video/") && !mediaType.equals("VIDEO", true)) return@forEach
                val playback = info.optString("url").takeIf { it.startsWith("https://") }
                    ?: return@forEach
                val ext = info.optJSONObject("extmetadata")
                val rawTitle = pageObj.optString("title").removePrefix("File:")
                val title = rawTitle.substringBeforeLast('.').replace('_', ' ').trim()
                if (title.isBlank()) return@forEach

                add(
                    VodItem(
                        id = "commons:${pageObj.optLong("pageid")}",
                        title = title,
                        overview = extValue(ext, "ImageDescription"),
                        posterUrl = info.optString("thumburl").takeIf(String::isNotBlank),
                        year = extValue(ext, "DateTimeOriginal").take(4).takeIf { it.length == 4 },
                        language = "und",
                        playbackUrl = playback,
                        source = "Wikimedia Commons",
                        catalog = source.name,
                        detailUrl = info.optString("descriptionurl").takeIf(String::isNotBlank),
                        licenseName = extValue(ext, "LicenseShortName").takeIf(String::isNotBlank),
                        licenseUrl = extValue(ext, "LicenseUrl").takeIf(String::isNotBlank),
                        attribution = extValue(ext, "Artist").takeIf(String::isNotBlank),
                        subtitleLookupKey = pageObj.optString("title").trim()
                    )
                )
            }
        }
    }

    private fun commonsDetails(item: VodItem): VodItem {
        val fileTitle = item.subtitleLookupKey ?: return item
        val discovered = COMMONS_SUBTITLE_LANGUAGES.mapNotNull { language ->
            val url = WikimediaSubtitleSupport.timedTextUrl(fileTitle, language.apiCode)
            val body = getText(url) ?: return@mapNotNull null
            if (!WikimediaSubtitleSupport.looksLikeSubtitle(body)) return@mapNotNull null

            VodSubtitle(
                uri = url,
                language = language.mediaLanguage,
                label = language.label,
                mimeType = "text/vtt",
                isDefault = language.mediaLanguage == "pt-BR" || language.mediaLanguage == "pt"
            )
        }

        return item.copy(
            subtitles = VodSubtitleSupport.preferPortuguese(item.subtitles + discovered)
        )
    }

    private fun locPage(source: LocCatalog, page: Int): List<VodItem> {
        val root = getJson(
            "https://www.loc.gov/collections/${source.slug}/?fo=json&c=$LOC_PAGE_SIZE&sp=$page"
        ) ?: return emptyList()
        val results = root.optJSONArray("results") ?: return emptyList()

        return buildList {
            for (i in 0 until results.length()) {
                val result = results.optJSONObject(i) ?: continue
                val title = result.optString("title").trim()
                val id = result.optString("id").ifBlank { result.optString("url") }
                if (title.isBlank() || id.isBlank()) continue
                val direct = firstMediaUrl(result)
                val images = result.optJSONArray("image")
                val poster = images?.optString(0)?.takeIf(String::isNotBlank)
                add(
                    VodItem(
                        id = "loc:${source.slug}:${id.hashCode()}",
                        title = title,
                        overview = jsonText(result.opt("description")),
                        posterUrl = poster,
                        year = jsonText(result.opt("date")).take(4).takeIf { it.length == 4 },
                        language = "und",
                        playbackUrl = direct,
                        source = "Library of Congress",
                        catalog = source.name,
                        detailUrl = result.optString("url").takeIf(String::isNotBlank)
                            ?: result.optString("id").takeIf(String::isNotBlank),
                        licenseName = jsonText(result.opt("rights")).takeIf(String::isNotBlank)
                            ?: "Direitos conforme registro da Library of Congress"
                    )
                )
            }
        }
    }

    private fun locDetails(item: VodItem): VodItem {
        val detail = item.detailUrl ?: return item
        val separator = if ('?' in detail) "&" else "?"
        val root = getJson(detail + separator + "fo=json") ?: return item
        return item.copy(playbackUrl = firstMediaUrl(root) ?: item.playbackUrl)
    }

    private fun firstMediaUrl(value: Any?): String? {
        val urls = mutableListOf<String>()
        collectUrls(value, urls)
        return urls
            .filter { url ->
                val clean = url.substringBefore('?').lowercase()
                clean.endsWith(".mp4") || clean.endsWith(".webm") ||
                    clean.endsWith(".m4v") || clean.endsWith(".mov")
            }
            .sortedByDescending { url ->
                val lower = url.lowercase()
                when {
                    ".mp4" in lower -> 4
                    ".webm" in lower -> 3
                    ".m4v" in lower -> 2
                    else -> 1
                }
            }
            .firstOrNull()
    }

    private fun collectUrls(value: Any?, output: MutableList<String>) {
        when (value) {
            is JSONObject -> value.keys().forEach { collectUrls(value.opt(it), output) }
            is JSONArray -> for (i in 0 until value.length()) collectUrls(value.opt(i), output)
            is String -> if (value.startsWith("https://")) output += value
        }
    }

    private fun getJson(url: String): JSONObject? =
        getText(url)?.let { runCatching { JSONObject(it) }.getOrNull() }

    private fun getText(url: String): String? {
        val request = Request.Builder()
            .url(url)
            .header("Accept", "*/*")
            .header("User-Agent", "SANCHESTV/2.8 AndroidTV (open movie catalog)")
            .build()

        return runCatching {
            client.newCall(request).execute().use { response ->
                if (!response.isSuccessful) return@use null
                response.body.string()
            }
        }.getOrNull()
    }

    private fun videoScore(name: String, format: String): Int {
        val extScore = when {
            name.endsWith(".mp4") || name.endsWith(".m4v") -> 100
            name.endsWith(".webm") -> 90
            name.endsWith(".mkv") -> 80
            name.endsWith(".mov") -> 70
            name.endsWith(".ogv") -> 60
            else -> return 0
        }
        val formatBonus = when {
            "h.264" in format.lowercase() || "mpeg4" in format.lowercase() -> 20
            "webm" in format.lowercase() -> 10
            else -> 0
        }
        val penalty = if ("sample" in name || "trailer" in name || "thumb" in name) 80 else 0
        return extScore + formatBonus - penalty
    }

    private fun extValue(ext: JSONObject?, key: String): String =
        ext?.optJSONObject(key)?.optString("value").orEmpty()
            .replace(Regex("<[^>]+>"), " ")
            .replace("&quot;", "\"")
            .replace("&amp;", "&")
            .trim()

    private fun jsonText(value: Any?): String = when (value) {
        is JSONArray -> buildList {
            for (i in 0 until value.length()) {
                value.optString(i).takeIf(String::isNotBlank)?.let(::add)
            }
        }.joinToString(" • ")
        is String -> value
        is Number -> value.toString()
        else -> ""
    }

    private fun jsonStrings(value: Any?): List<String> = when (value) {
        is JSONArray -> buildList {
            for (i in 0 until value.length()) {
                value.optString(i).takeIf(String::isNotBlank)?.let(::add)
            }
        }
        is String -> listOf(value)
        else -> emptyList()
    }

    private fun encode(value: String): String =
        URLEncoder.encode(value, "UTF-8").replace("+", "%20")

    private fun encodePath(value: String): String =
        URLEncoder.encode(value, "UTF-8")
            .replace("+", "%20")
            .replace("%2F", "/")

    private data class ArchiveCatalog(
        val name: String,
        val query: String,
        val requiresOpenRightsSignal: Boolean = false
    )

    private data class CommonsCatalog(
