                page.coerceAtLeast(1) + "&q=" + encode(query)
        )

    private fun fetch(url: String): List<VodItem> {
        val items = getJson(client, url)
            ?.optJSONObject("collection")
            ?.optJSONArray("items") ?: return emptyList()

        return buildList {
            for (i in 0 until items.length()) {
                val raw = items.optJSONObject(i) ?: continue
                val data = raw.optJSONArray("data")?.optJSONObject(0) ?: continue
                val nasaId = data.optString("nasa_id").trim()
                val title = CinemaMetadataNormalizer.text(data.optString("title"))
                if (nasaId.isBlank() || title.isBlank()) continue
                val preview = raw.optJSONArray("links")
                    ?.optJSONObject(0)
                    ?.optString("href")
                    ?.takeIf(String::isNotBlank)

                add(
                    VodItem(
                        id = "nasa:$nasaId",
                        title = title,
                        overview = CinemaMetadataNormalizer.text(
                            data.optString("description")
                        ),
                        posterUrl = preview,
                        year = CinemaMetadataNormalizer.year(
                            data.optString("date_created")
                        ),
                        genres = jsonStrings(data.opt("keywords")).take(12),
                        source = "NASA Image and Video Library",
                        catalog = "NASA • Vídeos e documentários",
                        detailUrl = "https://images.nasa.gov/details/" + encodePath(nasaId),
                        licenseName = "NASA Media Usage Guidelines",
                        licenseUrl = "https://www.nasa.gov/nasa-brand-center/images-and-media/",
                        attribution = data.optString("center").takeIf(String::isNotBlank)
                            ?: "NASA",
                        rightsStatus = RightsStatus.OPEN_LICENSE,
                        providers = listOf("NASA"),
                        externalIds = mapOf("nasa_id" to nasaId)
                    )
                )
            }
        }
    }
