private class EuropeanaProvider(
    private val client: OkHttpClient,
    private val apiKey: String
) : CinemaProvider {
    override val key = "europeana"
    override val name = "Europeana • Open Video"
    override val enabled = apiKey.isNotBlank()
    override val requiresKey = true

    override suspend fun loadPage(page: Int): List<VodItem> =
        fetch("*", page)

    override suspend fun search(query: String, page: Int): List<VodItem> =
        fetch(query, page)

    private fun fetch(query: String, page: Int): List<VodItem> {
        if (!enabled) return emptyList()
        val start = ((page.coerceAtLeast(1) - 1) * 40) + 1
        val url = "https://api.europeana.eu/record/v2/search.json?wskey=" +
            encode(apiKey) +
            "&query=" + encode(query) +
            "&qf=TYPE%3AVIDEO&qf=REUSABILITY%3Aopen" +
            "&media=true&profile=rich&rows=40&start=" + start

        val items = getJson(client, url)?.optJSONArray("items")
            ?: return emptyList()

        return buildList {
            for (i in 0 until items.length()) {
                val raw = items.optJSONObject(i) ?: continue
                val id = raw.optString("id").trim()
                val title = firstString(raw.opt("title"))
                if (id.isBlank() || title.isBlank()) continue
                val rights = firstString(raw.opt("rights"))
                val direct = firstString(raw.opt("edmIsShownBy"))
                    .takeIf(::looksLikeVideoUrl)

                add(
                    VodItem(
                        id = "eu:" + id.hashCode(),
                        title = CinemaMetadataNormalizer.text(title),
                        overview = CinemaMetadataNormalizer.text(
                            firstString(raw.opt("dcDescription"))
                        ),
                        posterUrl = firstString(raw.opt("edmPreview"))
                            .takeIf(String::isNotBlank),
                        year = CinemaMetadataNormalizer.year(
                            firstString(raw.opt("year"))
                        ),
                        playbackUrl = direct,
                        source = "Europeana",
                        catalog = "Europeana • Open Video",
                        detailUrl = firstString(raw.opt("guid"))
                            .takeIf(String::isNotBlank),
                        licenseName = rights.takeIf(String::isNotBlank)
                            ?: "Europeana reusability=open",
                        licenseUrl = rights.takeIf { it.startsWith("http") },
                        rightsStatus = RightsStatus.OPEN_LICENSE,
                        providers = listOf("Europeana"),
                        externalIds = mapOf("europeana" to id)
                    )
                )
            }
        }
    }
}

private class DplaProvider(
    private val client: OkHttpClient,
