        if (query.isNotBlank()) {
            base.append("&q=").append(encode(query))
        }

        val docs = getJson(client, base.toString())?.optJSONArray("docs")
            ?: return emptyList()

        return buildList {
            for (i in 0 until docs.length()) {
                val raw = docs.optJSONObject(i) ?: continue
                val id = raw.optString("id")
                val source = raw.optJSONObject("sourceResource")
                val title = firstString(source?.opt("title"))
                if (id.isBlank() || title.isBlank()) continue
                val rights = firstString(source?.opt("rights"))
                val shownAt = firstString(raw.opt("isShownAt"))

                add(
                    VodItem(
                        id = "dpla:$id",
                        title = CinemaMetadataNormalizer.text(title),
                        overview = CinemaMetadataNormalizer.text(
                            firstString(source?.opt("description"))
                        ),
                        posterUrl = firstString(raw.opt("object"))
                            .takeIf(String::isNotBlank),
                        year = CinemaMetadataNormalizer.year(
                            firstString(source?.opt("date"))
                        ),
                        source = "DPLA",
                        catalog = "DPLA • Moving Image",
                        detailUrl = shownAt.takeIf(String::isNotBlank),
                        licenseName = rights.takeIf(String::isNotBlank),
                        rightsStatus = CinemaRightsEngine.classify(
                            "DPLA",
                            rights,
                            null
                        ),
                        providers = listOf("DPLA"),
                        externalIds = mapOf("dpla" to id)
                    )
                )
            }
        }
    }
}

object CinemaMetadataNormalizer {
    fun text(value: String): String =
        value.replace(Regex("<[^>]+>"), " ")
            .replace("&amp;", "&")
            .replace("&quot;", "\"")
            .replace("&#39;", "'")
            .replace(Regex("\\s+"), " ")
            .trim()

    fun year(value: String): String? =
        Regex("""\b(18|19|20)\d{2}\b""")
            .find(value)
            ?.value
}

private fun getJson(client: OkHttpClient, url: String): JSONObject? {
    val request = Request.Builder()
        .url(url)
        .header("Accept", "application/json")
        .header("User-Agent", "SANCHESTV/2.9 AndroidTV InfiniteCinema")
        .build()

    return runCatching {
        client.newCall(request).execute().use { response ->
            if (!response.isSuccessful) return@use null
            JSONObject(response.body.string())
        }
    }.getOrNull()
}

private fun firstMediaUrl(value: Any?): String? {
    val urls = mutableListOf<String>()
    collectUrls(value, urls)
    return urls.filter(::looksLikeVideoUrl)
        .sortedByDescending(::videoUrlScore)
        .firstOrNull()
}

private fun collectUrls(value: Any?, output: MutableList<String>) {
    when (value) {
        is JSONObject -> value.keys().forEach { collectUrls(value.opt(it), output) }
        is JSONArray -> for (i in 0 until value.length()) collectUrls(value.opt(i), output)
        is String -> if (value.startsWith("https://")) output += value
    }
}

private fun looksLikeVideoUrl(url: String): Boolean {
    val clean = url.substringBefore('?').lowercase()
    return clean.endsWith(".mp4") ||
        clean.endsWith(".m4v") ||
        clean.endsWith(".webm") ||
        clean.endsWith(".mov") ||
        clean.endsWith(".ogv") ||
        clean.endsWith(".m3u8") ||
        clean.endsWith(".mpd")
}

private fun videoUrlScore(url: String): Int {
    val lower = url.lowercase()
    return when {
        ".m3u8" in lower -> 130
        ".mpd" in lower -> 125
        ".mp4" in lower && ("1080" in lower || "720" in lower) -> 120
        ".mp4" in lower -> 110
        ".webm" in lower -> 100
        ".m4v" in lower -> 90
        ".mov" in lower -> 80
        ".ogv" in lower -> 70
        else -> 0
    }
}

private fun videoScore(name: String, format: String): Int {
    val lower = name.substringBefore('?').lowercase()
    var score = videoUrlScore(lower)
    if (score == 0) return 0
    val fmt = format.lowercase()
    if ("h.264" in fmt || "mpeg4" in fmt) score += 20
    if ("sample" in lower || "trailer" in lower || "preview" in lower) score -= 80
    return score
}

private fun jsonText(value: Any?): String = when (value) {
    is JSONArray -> buildList {
        for (i in 0 until value.length()) {
            value.optString(i).takeIf(String::isNotBlank)?.let(::add)
        }
    }.joinToString(" • ")
    is String -> value
    is Number -> value.toString()
    else -> ""
}

private fun jsonStrings(value: Any?): List<String> = when (value) {
    is JSONArray -> buildList {
        for (i in 0 until value.length()) {
            value.optString(i).takeIf(String::isNotBlank)?.let(::add)
        }
    }
    is String -> listOf(value)
    else -> emptyList()
}

private fun firstString(value: Any?): String = when (value) {
    is JSONArray -> value.optString(0)
    is String -> value
    else -> ""
}

private fun encode(value: String): String =
    URLEncoder.encode(value, "UTF-8").replace("+", "%20")

private fun encodePath(value: String): String =
    URLEncoder.encode(value, "UTF-8")
        .replace("+", "%20")
        .replace("%2F", "/")

